  insert into geo_ingest.match_candidates(
    run_id,raw_place_id,canonical_place_id,match_type,
    name_score,distance_m,admin_score,overall_score,decision,reason
  )
  select
    r.run_id,r.id,v.canonical_place_id,v.match_type,
    case when v.decision='auto_match' then 82 else 50 end,
    null,v.admin_score,v.overall_score,v.decision,v.reason
  from v
  join geo_ingest.raw_places r
    on r.run_id='bb780042-0d81-40f4-8a8a-debb8f2ff2b1'::uuid and r.source_code='geonames' and r.source_id=v.source_id;

update geo_ingest.runs
    set stage='promotion',
        status=case when 1080>0 then 'blocked' else 'passed' end,
        matched_count=508,
        new_count=0,
        review_count=1080,
        metrics=metrics || jsonb_build_object(
          'mode','existing_only',
          'candidate_rows',1588,
          'matched_count',508,
          'new_count',0,
          'review_count',1080,
          'promotion_allowed',false
        )
    where id='bb780042-0d81-40f4-8a8a-debb8f2ff2b1'::uuid;

update geo_ingest.source_snapshots s
    set status='validated'
    from geo_ingest.runs r
    where r.id='bb780042-0d81-40f4-8a8a-debb8f2ff2b1'::uuid and s.id=r.snapshot_id;
